def get_perimeter(n):
    # Flood set F_n = {(x,y) : |x| + |y| <= n}
    # Perimeter is the number of edges between F_n and its complement.
    f_n = set()
    for x in range(-n, n + 1):
        for y in range(-(n - abs(x)), (n - abs(x)) + 1):
            f_n.add((x, y))

    perimeter = 0
    for (x, y) in f_n:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in f_n:
                perimeter += 1
    return perimeter

for n in range(1, 6):
    print(f"n={n}, perimeter={get_perimeter(n)}")

