    for x in range(-(n + 1), (n + 1) + 1):
        for y in range(-(n + 1 - abs(x)), (n + 1 - abs(x)) + 1):
            diamond_next.add((x, y))
    p2 = get_perimeter(diamond_next)

    print(f"Diamond: p1={p1}, p2={p2}, growth={p2-p1}")

