        for y in range(-(n + 1), (n + 1) + 1):
            square_next.add((x, y))
    p2_sq = get_perimeter(square_next)

    print(f"Square: p1_sq={p1_sq}, p2_sq={p2_sq}, growth={p2_sq-p1_sq}")

